import { COMMERCIAL_RESULTS_PAGE_NAME } from 'pages/pillars/ValueCreation/CommercialResults/constants';

export const isPerformanceToolFilterPage = (pageName: string): boolean =>
  pageName?.includes('value-creation/performance-tool');

/**
 * Pages where the sub-brand quick filter merges into the brand chip
 * (label stays "Brand", value shows sub-brand when selected).
 */
export const isSubBrandMergedIntoBrandChipPage = (pageName: string): boolean =>
  isPerformanceToolFilterPage(pageName) ||
  pageName === COMMERCIAL_RESULTS_PAGE_NAME;

export const hasActiveSubBrandQuickFilterValue = (
  value: string | number | null | undefined,
): boolean => {
  if (value == null || value === '') return false;
  if (typeof value === 'string') return value.toUpperCase() !== 'ALL';
  return true;
};
